		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = static_cast<num_t>(i * (k + 1) % nk) / static_cast<num_t>(nk);
	});

	// B[k][j] = k*(j+2) % nj / nj
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = static_cast<num_t>(k * (j + 2) % nj) / static_cast<num_t>(nj);
	});
