	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

#pragma scop
	// ---------------------------------------------------------------------
	// 1) Scale C by beta
	//    Traversal order is the natural one for C: i outer, j inner.
	// ---------------------------------------------------------------------
	traverser(C).for_each([=](auto state) {
		C[state] *= beta;
