void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

#pragma scop

	// --------------------------------------------------------------------
	// 1. Determine j-block size and create a tiling proto-structure
	// --------------------------------------------------------------------
	//
	// We would like to tile the j dimension by a (compile-time-tunable)
	// size tuning::j_block_size, but into_blocks assumes that the original
	// length is a multiple of the block size.
	//
