	// both:
	//   - divides NJ, and
	//   - does not exceed tuning::j_block_size.
	//
	// If no divisor > 1 satisfies this, we fall back to block size 1
	// (i.e., effectively no blocking). This guarantees correctness for
	// arbitrary problem sizes while still allowing tuning via
	// tuning::j_block_size when the dimensions are favorable.

	const std::size_t nj = C | get_length<'j'>();

	// Early exit for degenerate cases (no columns).
	if (nj == 0) {
		return;
	}

	std::size_t j_block = tuning::j_block_size;
	if (j_block > nj)
		j_block = nj;

	while (j_block > 1 && (nj % j_block) != 0)
		j_block /= 2;

	// At this point, 1 <= j_block <= nj and nj % j_block == 0.
	// Construct a proto-structure that logically splits 'j' into:
	//   'J' = block index, 'j' = index within block.
	// This is *only* a change in the logical traversal order; the physical
	// layout of the matrices remains unchanged.
	const auto j_blocking = into_blocks<'j', 'J', 'j'>(j_block);

	// --------------------------------------------------------------------
	// 2. Scale C by beta: C[i,j] *= beta
	// --------------------------------------------------------------------
	//
	// We traverse C with the tiling order applied:
	//   for i
	//     for J  (block over j)
	//       for j in block
	//
	// The state passed into the innermost lambda still uses the original
	// dimensions {i, j} (no 'J'), so indexing C[state] refers to the
	// correct element C[i,j].

	traverser(C)
		.order(j_blocking)
		.template for_dims<'i', 'J'>([=](auto trav_iJ) {
			trav_iJ.for_each([=](auto state) {
				C[state] *= beta;
			});
		});

	// --------------------------------------------------------------------
	// 3. GEMM part: C[i,j] += alpha * sum_k A[i,k] * B[k,j]
	// --------------------------------------------------------------------
	//
	// We use a joint traverser over A, B, and C with the same j-tiling
	// applied. Dimensions:
	//   A: i, k
	//   B: k, j
	//   C: i, j
	// so the combined logical dimensions are {i, j, k}.
	//
	// With tiling applied, the traversal order becomes:
	//   for i
	//     for k
	//       for J (blocks over j)
	//         for j in block
	//
	// For each fixed (i,k,J) triple we:
	//   - load A[i,k] once (and multiply by alpha),
	//   - iterate over all j in the current block,
	//   - update C[i,j] and read B[k,j] with j as the innermost index.
	//
	// This matches the row-major-in-j layout of C and B, improving cache
	// efficiency and enabling vectorization along j.

	auto trav_ABC = traverser(A, B, C).order(j_blocking);

	trav_ABC.template for_dims<'i', 'k', 'J'>([=](auto trav_ikJ) {
		// trav_ikJ has i, k, and J fixed; j is left to vary in for_each.
		// .state() returns a state expressed in the *original* dimensions
		// (i.e. {i, k} here; 'J' is not part of the state), so we can use
		// it directly to index A.
		auto state_ik = trav_ikJ.state();
		const num_t a_ik_scaled = alpha * A[state_ik];

		// Iterate over all j in the current (i,k,J) block and update C.
		trav_ikJ.for_each([=](auto state) {
			// state contains {i, j, k} in original coordinates.
			C[state] += a_ik_scaled * B[state];
		});
	});

#pragma endscop
