// so that all innermost accesses are along the contiguous dimension.
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// Layouts are written from inner to outer:
	//   scalar ^ inner_dim ^ outer_dim
	// so j_vec ^ i_vec => 'j' inner (contiguous), 'i' outer.
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec); // C: i x j, contiguous in j
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // A: i x k, contiguous in k
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec); // B: k x j, contiguous in j
} tuning;

// Tunable blocking parameters (currently unused in the kernel logic, but kept
// here so that the kernel can be easily extended with blocking/tiling if
// desired for a specific cache hierarchy).
[[maybe_unused]] constexpr std::size_t I_BLOCK = 64;
[[maybe_unused]] constexpr std::size_t J_BLOCK = 64;
[[maybe_unused]] constexpr std::size_t K_BLOCK = 64;

// Array initialization
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// Cache the lengths once; get_length is cheap but this makes it explicit
	const std::size_t ni = C | get_length<'i'>();
	const std::size_t nk = A | get_length<'k'>();
	const std::size_t nj = B | get_length<'j'>();

	// C[i][j] = (i*j+1) % ni / ni
	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 1) % ni) / ni;
	});

	// A[i][k] = i*(k+1) % nk / nk
	traverser(A).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)(i * (k + 1) % nk) / nk;
	});

	// B[k][j] = k*(j+2) % nj / nj
	traverser(B).for_each([&](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)(k * (j + 2) % nj) / nj;
	});
}

// Main computational kernel (GEMM)
// Form C := alpha*A*B + beta*C,
// A is NIxNK, B is NKxNJ, C is NIxNJ.
//
// Optimized with respect to the original version:
//
//  - All loop nests are expressed using Noarr traversers / for_dims.
//  - We choose loop order i (rows) -> k -> j (columns).
//    * C(i, :) and B(k, :) are both contiguous in 'j', so having 'j' as the
//      innermost dimension yields unit-stride accesses for both arrays.
//    * A(i, k) is contiguous in 'k' and we walk k in the middle loop,
//      which keeps A accesses sequential in memory.
//  - The beta scaling of C is done in a separate traversal over C only
//    (pure streaming, no extra indirections).
//  - For each (i, k) pair we load A[i, k] once into a scalar (aik) and
//    reuse it across all j in the innermost loop.
//
// This preserves the mathematical semantics of GEMM while improving the
// cache-friendliness of the memory access pattern.
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

#pragma scop
	// ---------------------------------------------------------------------
	// Phase 1: C[i][j] *= beta
	// ---------------------------------------------------------------------
	traverser(C).for_each([&](auto state) {
		C[state] *= beta;
	});

	// ---------------------------------------------------------------------
	// Phase 2: C[i][j] += alpha * A[i][k] * B[k][j]
	//
	// Loop structure (in terms of dimensions):
	//   for i
	//     for k
	//       aik = A[i, k]
	//       for j
	//         C[i, j] += alpha * aik * B[k, j]
	//
	// Implemented with a multi-structure traverser so that the state
	// (i, j, k) can be shared across A, B, and C. We explicitly choose
	// the order of dimensions using for_dims:
	//   - 'i' as the outermost loop,
	//   - 'k' as the middle loop,
	//   - 'j' as the innermost loop (via for_each over the remaining dim).
	// ---------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; remaining varying dimensions are 'k' and 'j'

		// Middle loop over 'k'
		trav_i.template for_dims<'k'>([&](auto trav_k) {
			// trav_k has 'i' and 'k' fixed; remaining varying dimension is 'j'

			// Reuse A[i, k] across all j in this (i, k) slice
			const num_t aik = A[trav_k];

			// Innermost loop over 'j'
			trav_k.for_each([&](auto state) {
				// state contains (i, j, k). Bags ignore dimensions they
				// don't have in their layout, so the same state can be used
				// for A, B, and C.
				C[state] += alpha * aik * B[state];
			});
		});
	});
#pragma endscop
