void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// Cache lengths outside of the traversals – they are constant
	const std::size_t ni = C | get_length<'i'>();
	const std::size_t nk = A | get_length<'k'>();
	const std::size_t nj = B | get_length<'j'>();

	// C[i][j] = (i*j+1) % ni / ni
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 1) % ni) / ni;
	});

	// A[i][k] = i*(k+1) % nk / nk
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)(i * (k + 1) % nk) / nk;
	});

	// B[k][j] = k*(j+2) % nj / nj
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)(k * (j + 2) % nj) / nj;
	});
}

// Main computational kernel (GEMM)
// Form C := alpha*A*B + beta*C,
// A is NIxNK, B is NKxNJ, C is NIxNJ
//
// Optimized traversal:
// 1. Scale C once: C[i][j] *= beta
// 2. Use an (i, k, j) loop order expressed via traversers:
//       for i
//         for k
//           tmp = alpha * A[i,k];
//           for j
//             C[i,j] += tmp * B[k,j];
//    This gives:
//    - B[k,*] accessed contiguously in j
//    - C[i,*] accessed contiguously in j
//    - A[i,k] loaded once per (i,k) pair and reused across the inner j-loop
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

#pragma scop
	// ---------------------------------------------------------------------
	// Step 1: scale C by beta (C[i][j] *= beta)
	// ---------------------------------------------------------------------
	traverser(C).for_each([=](auto state) {
		C[state] *= beta;
	});

	// ---------------------------------------------------------------------
	// Step 2: GEMM core with cache-friendly traversal
	// Traversal order: i (rows of C and A), then k, then j (columns of C/B)
	// Implemented using:
	//   traverser(C,A,B).for_dims<'i','k'>(...) and inner .for_each(...)
	// ---------------------------------------------------------------------

	// Tunable parameter: this is here for future experimentation (e.g., to
	// drive unrolling or planner-based blocking if extended).
	constexpr std::size_t IK_TUNE = 1;
	(void)IK_TUNE; // suppress unused warning for now

	traverser(C, A, B)
		.template for_dims<'i', 'k'>([=](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed; only 'j' remains to iterate

			// Extract the fixed (i,k) state once
			auto state_ik = trav_ik.state();

			// Load A[i,k] once and scale by alpha
			const num_t a_ik = A[state_ik];
			const num_t scaled_a_ik = alpha * a_ik;

			// Now traverse over j only; this corresponds to the innermost loop
			//   for (j) C[i][j] += scaled_a_ik * B[k][j];
			trav_ik.for_each([=](auto state) {
				C[state] += scaled_a_ik * B[state];
			});
		});
#pragma endscop
}

} // namespace

