// Main computational kernel (GEMM)
// Form C := alpha*A*B + beta*C,
// A is NIxNK, B is NKxNJ, C is NIxNJ
//
// Optimized layout-aware implementation:
//   - First scale C by beta in a separate, purely linear pass
//     (very easy for the compiler to vectorize).
//   - Then compute the product using an i–k–j loop ordering:
//
//       for (i)
//         for (k)
//           let a_ik = alpha * A[i,k];
//           for (j)
//             C[i,j] += a_ik * B[k,j];
//
//     With the chosen layouts (C: i×j, A: i×k, B: k×j) this yields:
//       * unit-stride reads of rows of A (varying k),
//       * unit-stride reads of rows of B (varying j at fixed k),
//       * unit-stride updates of rows of C (varying j at fixed i),
//     improving cache locality and SIMD utilization.
//
// All loops are expressed using Noarr traversers.
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

#pragma scop
	// 1) Scale C by beta: single, cache-friendly pass over C.
	traverser(C).for_each([&](auto state) {
		C[state] *= beta;
	});

	// 2) Main GEMM:
	//    Use traverser(C, A, B) so the same index state can address
	//    all three matrices simultaneously. We express the loop nest
	//    as:
	//
	//      for (i)
	//        for (k)
	//          a_ik = alpha * A[i,k];
	//          for (j)
	//            C[i,j] += a_ik * B[k,j];
	//
	//    via nested for_dims calls.
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has dimension 'i' fixed; free dimensions are 'k' and 'j'.
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed; only 'j' remains free.
			auto ik_state = trav_ik.state();

			// Load A[i,k] once per (i,k) and pre-scale by alpha.
			num_t a_ik = alpha * A[ik_state];

			// Inner-most loop over 'j' with unit-stride accesses:
			//   - C[i,j] (row of C)
			//   - B[k,j] (row of B)
			trav_ik.for_each([&](auto ijk_state) {
				C[ijk_state] += a_ik * B[ijk_state];
			});
		});
	});
#pragma endscop
}

